-- Encryption enforcement in the database: a registered sensitive column can never receive plaintext once its table is
-- activated, whatever the client (service role, user JWT, SQL function, manual psql).
--   field_enc_enforcement(table_name, active)  per-table activation flag, default OFF.
--   enc_reject_plaintext(cols...)              BEFORE INSERT OR UPDATE trigger function. For each listed column whose
--                                              value is new (INSERT) or changed (UPDATE, IS DISTINCT FROM), a non-null
--                                              value must be '' / '{}' / '[]' / enc:v1: / enc:v2: (arrays: every element).
--                                              The error names table + column only, never the value.
-- Activation is one-way: active true -> false (or deleting an active row) is rejected; turning enforcement off needs
-- a reviewed migration. Rollout per table: deploy code -> backfill to 0 plaintext -> set active = true.
-- The per-table trigger list below the marker is GENERATED from apps/web/lib/security/field-registry.ts.

create table if not exists public.field_enc_enforcement (
  table_name text primary key,
  active boolean not null default false,
  activated_at timestamptz,
  updated_at timestamptz not null default now()
);
alter table public.field_enc_enforcement enable row level security;
revoke all on public.field_enc_enforcement from anon, authenticated;

create or replace function public.field_enc_enforcement_guard() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    if old.active then raise exception 'field_enc_enforcement: cannot delete an active table (%)', old.table_name; end if;
    return old;
  end if;
  if tg_op = 'UPDATE' and old.active and not new.active then
    raise exception 'field_enc_enforcement: % is active; deactivation is not allowed', old.table_name;
  end if;
  if tg_op = 'UPDATE' and old.active then
    new.activated_at := old.activated_at;
  elsif new.active then
    new.activated_at := now();
  else
    new.activated_at := null;
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists field_enc_enforcement_guard on public.field_enc_enforcement;
create trigger field_enc_enforcement_guard before insert or update or delete on public.field_enc_enforcement
  for each row execute function public.field_enc_enforcement_guard();

create or replace function public.enc_value_ok(v jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select case
    when v is null or jsonb_typeof(v) = 'null' then true
    when jsonb_typeof(v) = 'string' then (v #>> '{}') = '' or (v #>> '{}') ~ '^enc:v[12]:'
    when jsonb_typeof(v) = 'array' then not exists (
      select 1 from jsonb_array_elements(v) e
      where not (jsonb_typeof(e) = 'string' and ((e #>> '{}') = '' or (e #>> '{}') ~ '^enc:v[12]:')))
    when jsonb_typeof(v) = 'object' then v = '{}'::jsonb
    else false end
$$;

-- SECURITY DEFINER: the flag table is RLS-locked, and user-JWT writes must still see the flag (otherwise a user
-- session would silently skip enforcement).
create or replace function public.enc_reject_plaintext() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  c text;
  nj jsonb;
  oj jsonb;
begin
  if not coalesce((select e.active from public.field_enc_enforcement e where e.table_name = tg_table_name), false) then
    return new;
  end if;
  nj := to_jsonb(new);
  if tg_op = 'UPDATE' then oj := to_jsonb(old); end if;
  foreach c in array tg_argv loop
    if tg_op = 'UPDATE' and (nj -> c) is not distinct from (oj -> c) then continue; end if;
    if not public.enc_value_ok(nj -> c) then
      raise exception 'enc_reject_plaintext: plaintext write to encrypted column %.% rejected', tg_table_name, c
        using errcode = '22023', hint = 'write through the field-encryption wrapper (lib/security/field-fetch.ts)';
    end if;
  end loop;
  return new;
end $$;
revoke all on function public.enc_reject_plaintext() from public, anon, authenticated;
revoke all on function public.field_enc_enforcement_guard() from public, anon, authenticated;

